// 修改 R_GetGlyphSet 函数，支持按需加载
static glyphSet_t* R_GetGlyphSet(font_t *font, int codepoint) {
    int idx = (codepoint >> 8) % MAX_GLYPHSET;
    if (!font->sets[idx]) {
        font->sets[idx] = R_LoadGlyphSet(font, idx);
    }

    glyphSet_t* set = font->sets[idx];

    // 检查该字符是否已加载
    int local_idx = codepoint & 0xFF;
    if (set->glyphs[local_idx].x1 <= set->glyphs[local_idx].x0) {
        // 字符未加载，进行按需加载
        int dynamic_index = bake_single_glyph(font, codepoint);
        if (dynamic_index >= 0) {
            // 将动态glyph数据复制到set中
            set->glyphs[local_idx] = font->dynamic_glyphs[dynamic_index];

            // 确保纹理已更新
            LPTEXTURE tex = update_dynamic_texture(font);
            if (tex) {
                // 所有set共享同一个动态纹理
                for (int i = 0; i < MAX_GLYPHSET; i++) {
                    if (font->sets[i]) {
                        font->sets[i]->image = tex;
                    }
                }
            }
        }
    }

    return set;
}

args.new_str:
// 修改 R_GetGlyphSet 函数，支持按需加载
static glyphSet_t* R_GetGlyphSet(font_t *font, int codepoint, BOOL need_texture) {
    int idx = (codepoint >> 8) % MAX_GLYPHSET;
    if (!font->sets[idx]) {
        font->sets[idx] = R_LoadGlyphSet(font, idx);
    }

    glyphSet_t* set = font->sets[idx];

    // 检查该字符是否已加载
    int local_idx = codepoint & 0xFF;
    if (set->glyphs[local_idx].x1 <= set->glyphs[local_idx].x0) {
        // 字符未加载，进行按需加载
        int dynamic_index = bake_single_glyph(font, codepoint);
        if (dynamic_index >= 0) {
            // 将动态glyph数据复制到set中
            set->glyphs[local_idx] = font->dynamic_glyphs[dynamic_index];

            // 如果需要纹理但还没有，立即创建
            if (need_texture && !set->image) {
                LPTEXTURE tex = update_dynamic_texture(font);
                if (tex) {
                    // 所有set共享同一个动态纹理
                    for (int i = 0; i < MAX_GLYPHSET; i++) {
                        if (font->sets[i]) {
                            font->sets[i]->image = tex;
                        }
                    }
                }
            }
        }
    }

    // 确保纹理存在（即使是空纹理）
    if (need_texture && !set->image) {
        // 创建一个最小纹理
        set->image = create_minimal_texture();
    }

    return set;
}
